// Тексты в коде пишутся по-русски и оборачиваются в t('...'); для английского берётся перевод из EN.
// {0}, {1} — подстановки: t('Глава {0}', 5).
let LANG='ru';
const RU_LANGS=['ru','be','kk','uk','uz','hy','az','ky','tg','tk'];
function detectLang(){
 const q=new URLSearchParams(location.search).get('lang');
 if(q)return q==='en'?'en':'ru';
 // v=396: на Playgama язык по умолчанию — английский; учитывается только выбор, сделанный в самой версии для Playgama (S.langPg),
 // а не сохранённый «ru» из других версий (общий localStorage при тестах)
 if(typeof PF!=='undefined'&&PF.name==='playgama')return S&&S.langPg||PF.lang();  // v=484: без выбора игрока — язык площадки (ru/be/uk/kk → русский)
 if(S&&S.lang)return S.lang;
 let l='';try{l=Y.lang();}catch(e){l='ru';}
 return RU_LANGS.includes(String(l).slice(0,2).toLowerCase())?'ru':'en';
}
function setLang(l){LANG=l==='en'?'en':'ru';}
function t(s,...a){
 let r=LANG==='en'&&EN[s]!==undefined?EN[s]:s;
 if(a.length)r=r.replace(/\{(\d)\}/g,(_,i)=>a[i]!==undefined?a[i]:'');
 return r;
}
